import { inflateSync, strFromU8 } from "fflate";
import type { StoredResultsPatchMap } from "../utils/raceResultsUpdater.ts";

const SNAPSHOT_B64 = "";

function decodeBase64(b64: string): Uint8Array {
  if (typeof atob === "function") {
    const bin = atob(b64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) {
      bytes[i] = bin.charCodeAt(i);
    }
    return bytes;
  }
  const buf = (globalThis as unknown as { Buffer?: { from(s: string, e: string): Uint8Array } }).Buffer?.from(b64, "base64");
  return buf ? new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength) : new Uint8Array(0);
}

function hydrateSnapshot(): { p: StoredResultsPatchMap; s: Record<string, string> } {
  try {
    const raw = strFromU8(inflateSync(decodeBase64(SNAPSHOT_B64)));
    return JSON.parse(raw) as { p: StoredResultsPatchMap; s: Record<string, string> };
  } catch (err) {
    console.error("Failed to hydrate liveResultsSnapshot:", err);
    return { p: {}, s: {} };
  }
}

const hydrated = hydrateSnapshot();
export const EMBEDDED_OFFICIAL_RESULTS_PATCH: StoredResultsPatchMap = hydrated.p || {};
export const VERIFIED_START_TIMES_2026_10_10: Record<string, string> = hydrated.s || {};
